//! `is_numbered_frame` — pure numbered-frame predicate (per-method record of the pty_faults parser).

/// A leading `<digits>:` frame (a Rust backtrace numbered frame), tolerating leading whitespace.
pub(crate) fn is_numbered_frame(t: &str) -> bool {
    let mut chars = t.chars();
    let mut saw_digit = false;
    for c in chars.by_ref() {
        if c.is_ascii_digit() {
            saw_digit = true;
        } else {
            return saw_digit && c == ':';
        }
    }
    false
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn leading_digits_then_colon_is_a_numbered_frame() {
        assert!(is_numbered_frame("12: core::panicking::panic"));
        assert!(is_numbered_frame("0:"));
    }

    #[test]
    fn no_leading_digits_or_no_colon_is_not() {
        assert!(!is_numbered_frame("at foo"), "no leading digit");
        assert!(!is_numbered_frame("12 no colon"), "digit run not terminated by a colon");
        assert!(!is_numbered_frame(""), "empty is not a frame");
    }
}
